const featured=[['Xtreme Boss Burger',381,'Beef burgers','hero-burger.jpg','The big bite','Big appetite? Meet the boss.','burgers','beef'],['Drip Beast Burger',376,'Beef burgers','burger-closeup.jpg','Fully loaded','Go all in. Napkins recommended.','burgers','beef'],['Triple Beast Burger',361,'Chicken burgers','dxb-chicken.jpg','Bring your appetite','For the seriously hungry.','burgers','chicken'],['Dubai Chocolate',179,'Gyptian desserts','dxb-chocolate-dessert.jpg','The sweet spot','A little indulgence. A lot of happiness.','desserts','all'],['Blueberry Heaven',278,'French toast','french-toast.jpg','Sweet escape','Your next sweet obsession.','french-toast','all'],['Signature House Pasta',276,'Rice & pasta','creamy-pasta.jpg','House favourite','Comfort, the DXB way.','rice-pasta','all']];
const track=document.querySelector('#featured-track');
track.innerHTML=featured.map(([name,price,type,img,tag,desc,category,filter])=>`<article class="food-card"><a href="#menu" data-category="${category}" data-burger="${filter}" aria-label="View ${name} in menu"><div class="food-photo ${img?'':'typographic-food'}">${img?`<img src="/assets/${img}" alt="Illustrative ${type.toLowerCase()} photography" loading="lazy" width="900" height="800">`:`<div class="food-word-art" aria-hidden="true">${name==='Triple Beast Burger'?'TRIPLE.<br>BEAST.<br>ENERGY.':'THE<br>SWEET<br>SIDE.'}<span>DXB カフェ</span></div>`}<span class="food-tag">${tag}</span><span class="food-price">₹${price}</span></div><div class="food-info"><span>${type}</span><h3>${name}</h3><p>${desc}</p></div></a></article>`).join('');
const tabs=document.querySelector('#menu-tabs');
tabs.innerHTML=categories.map((c,i)=>`<button id="tab-${c.id}" role="tab" aria-selected="${i===0}" aria-controls="menu-panel" tabindex="${i===0?0:-1}" data-category="${c.id}">${c.label}</button>`).join('');
let currentCategory='burgers',currentFilter='all',expanded=false;
const money=p=>typeof p==='number'?`₹${p}`:p.split(' / ').map(n=>'₹'+n).join(' / ');
function renderMenu(){const c=categories.find(c=>c.id===currentCategory);const items=c.items.filter(i=>c.id!=='burgers'||currentFilter==='all'||i[3]===currentFilter);const displayed=expanded?items:items.slice(0,6);
 document.querySelector('#menu-items').innerHTML=displayed.map(([name,price,description,type],i)=>`<article class="menu-item" style="--i:${i%6}"><span class="item-type">${type?type+' burger':c.label}</span><h3>${name}</h3><p>${description}</p><span class="item-price">${money(price)}</span></article>`).join('');
 document.querySelector('#menu-count').textContent=`${items.length} ${currentFilter==='all'?'':currentFilter+' '}favourites to choose from`;
 const more=document.querySelector('#show-menu');more.hidden=items.length<=6;more.textContent=expanded?'Show less':`View all ${items.length} ${c.label.toLowerCase()}`;
 document.querySelector('#burger-filters').hidden=c.id!=='burgers';
 document.querySelectorAll('[data-filter]').forEach(b=>{const on=b.dataset.filter===currentFilter;b.classList.toggle('selected',on);b.setAttribute('aria-pressed',on)});
}
function selectCategory(id,filter='all'){currentCategory=id;currentFilter=filter;expanded=false;const c=categories.find(c=>c.id===id);tabs.querySelectorAll('button').forEach(b=>{const on=b.dataset.category===id;b.setAttribute('aria-selected',on);b.tabIndex=on?0:-1});document.querySelector('#menu-panel').setAttribute('aria-labelledby','tab-'+id);const img=document.querySelector('#category-image');img.src='/assets/'+c.image;img.alt=`Illustrative photography for ${c.label.toLowerCase()}`;document.querySelector('#category-title').innerHTML=c.title;document.querySelector('#category-kicker').textContent=c.kicker;document.querySelector('#category-number').textContent=String(categories.indexOf(c)+1).padStart(2,'0');renderMenu();}
tabs.addEventListener('click',e=>{const b=e.target.closest('button');if(b)selectCategory(b.dataset.category)});
tabs.addEventListener('keydown',e=>{const buttons=[...tabs.querySelectorAll('button')];let i=buttons.indexOf(document.activeElement);if(e.key==='ArrowRight')i=(i+1)%buttons.length;else if(e.key==='ArrowLeft')i=(i-1+buttons.length)%buttons.length;else if(e.key==='Home')i=0;else if(e.key==='End')i=buttons.length-1;else return;e.preventDefault();buttons[i].focus();selectCategory(buttons[i].dataset.category)});
document.querySelector('#burger-filters').addEventListener('click',e=>{const b=e.target.closest('button');if(b){currentFilter=b.dataset.filter;expanded=false;renderMenu()}});
document.querySelector('#show-menu').addEventListener('click',()=>{expanded=!expanded;renderMenu()});
track.addEventListener('click',e=>{const a=e.target.closest('[data-category]');if(a)selectCategory(a.dataset.category,a.dataset.burger)});
renderMenu();
const reducedMotion=matchMedia('(prefers-reduced-motion: reduce)');
const prev=document.querySelector('#previous-food'),next=document.querySelector('#next-food');
function trackControls(){prev.disabled=track.scrollLeft<5;next.disabled=track.scrollLeft+track.clientWidth>=track.scrollWidth-5}
prev.addEventListener('click',()=>track.scrollBy({left:-track.querySelector('.food-card').getBoundingClientRect().width-22,behavior:reducedMotion.matches?'instant':'smooth'}));
next.addEventListener('click',()=>track.scrollBy({left:track.querySelector('.food-card').getBoundingClientRect().width+22,behavior:reducedMotion.matches?'instant':'smooth'}));
track.addEventListener('scroll',trackControls,{passive:true});window.addEventListener('resize',trackControls);trackControls();
if(!reducedMotion.matches){document.body.classList.add('motion-ready');const reveals=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');reveals.unobserve(e.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>reveals.observe(el));}
const sectionObserver=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting)navigation.querySelectorAll('a').forEach(a=>a.classList.toggle('active',a.hash==='#'+e.target.id))})},{rootMargin:'-15% 0px -60% 0px',threshold:0});
document.querySelectorAll('main section[id]').forEach(s=>sectionObserver.observe(s));
const dialog=document.querySelector('#image-dialog');
document.querySelectorAll('[data-photo]').forEach(button=>button.addEventListener('click',()=>{dialog.querySelector('img').src=button.dataset.photo;dialog.querySelector('img').alt=button.querySelector('img').alt;dialog.querySelector('p').textContent=button.dataset.caption;dialog.showModal();document.body.style.overflow='hidden'}));
function closePhoto(){dialog.close()}
dialog.querySelector('.dialog-close').addEventListener('click',closePhoto);
dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closePhoto()}});
dialog.addEventListener('close',()=>document.body.style.overflow='');
if(matchMedia('(hover:hover) and (pointer:fine)').matches&&!reducedMotion.matches){document.querySelectorAll('.button').forEach(button=>{button.addEventListener('pointermove',e=>{const r=button.getBoundingClientRect();button.style.transform=`translate(${(e.clientX-r.left-r.width/2)*.09}px, ${(e.clientY-r.top-r.height/2)*.15}px)`});button.addEventListener('pointerleave',()=>button.style.transform='')});let pending=false;window.addEventListener('scroll',()=>{if(!pending){pending=true;requestAnimationFrame(()=>{const hero=document.querySelector('.hero');if(scrollY<hero.offsetHeight)document.querySelector('.hero-image img').style.objectPosition=`50% ${50+scrollY*.025}%`;pending=false})}},{passive:true});const game=document.querySelector('.gaming-section');game.addEventListener('pointermove',e=>{const r=game.getBoundingClientRect();document.querySelector('.gaming-glow').style.background=`radial-gradient(ellipse at ${(e.clientX-r.left)/r.width*100}% ${(e.clientY-r.top)/r.height*100}%,#6632ab50,transparent 65%)`})}
document.querySelector('#year').textContent=new Date().getFullYear();
